-- challenge chal_quiz_nhp_101 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_101', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-1-1' AND is_deleted = false LIMIT 1), 'single-thread-race-quiz', 'Does a single thread protect the wallet?', 'Two payment requests for the same wallet run the same async handler at the same time. Predict the outcome before you read on.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_101'), 'Node.js runs your JavaScript on one thread. A wallet holds 100,000 and two POST /payments requests of 80,000 arrive together. Each runs:

const wallet = await repo.findById(walletId);
if (wallet.balance < amount) throw new Error(''INSUFFICIENT_FUNDS'');
await repo.save({ ...wallet, balance: wallet.balance - amount });

What can happen?', 'single_choice'::question_type, 'Every await hands control back to the event loop. Request A reads 100,000 and waits for the database; request B runs its findById in that gap and also reads 100,000. Both pass the check and both save 20,000. Two payments are approved but only one is charged - a lost update. A single thread only guarantees that synchronous code is not interrupted; anything spanning an await can interleave.', 1, 10
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_101') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Nothing bad: the second request waits until the first handler finishes, because Node.js is single-threaded.', false),
        ('Both requests can read 100,000 before either saves, so both are approved and the wallet ends at 20,000 - one debit is lost.', true),
        ('Node.js throws an error because two async functions modify the same object at once.', false),
        ('Both requests fail, because the database locks the row automatically while it is being read.', false)
    ) AS o(option_text, is_correct);

