-- challenge chal_quiz_nhp_111 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_111', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-1-2' AND is_deleted = false LIMIT 1), 'event-loop-under-load-quiz', 'What stalls every request on the instance?', 'One process, one thread, many concurrent requests. Predict which code freezes all of them before you read on.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_111'), 'To ''flush metrics as fast as possible'', a developer adds this to the order API:

function drain() {
  if (buffer.length > 0) metricsBatch.push(buffer.shift());
  process.nextTick(drain);
}
drain();

Each call does almost no work. What happens to incoming HTTP requests on this instance?', 'single_choice'::question_type, 'process.nextTick callbacks run before the event loop is allowed to move on, and the queue is drained until it is empty. drain() always queues itself again, so the queue is never empty and the loop never reaches the poll phase where new connections and request data are handled. No exception is thrown - this is not stack recursion - the process just spins at 100% CPU and stops answering, health checks included. Promise callbacks that keep queuing promise callbacks starve the loop the same way; use setImmediate or a timer for work that should repeat.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('They are served normally: nextTick callbacks are interleaved between requests.', false),
        ('The instance stops answering: the nextTick queue never empties, so the loop never gets to the phase that reads sockets.', true),
        ('Node.js throws RangeError: Maximum call stack size exceeded after a few thousand calls, and the process restarts.', false),
        ('Only timers are delayed; incoming requests are still handled because network I/O runs on libuv''s thread pool.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_111'), 'Inside an Express request handler of a payments API, which of these delay EVERY other in-flight request handled by the same Node.js process while they run? Select all that apply.', 'multiple_choice'::question_type, 'JSON.parse and crypto.pbkdf2Sync are synchronous: they run on the main thread and nothing else - no timer, no socket read, no other request - can run until they return. A slow database query or HTTP call is different: while it is awaited, the handler is suspended and the event loop keeps serving other requests. Slow I/O hurts only the request waiting on it; slow synchronous code hurts everyone.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_111') AND order_index = 2)
    RETURNING id
