-- challenge chal_quiz_nhp_114 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_114', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-1-2' AND is_deleted = false LIMIT 1), 'promise-all-rejection-quiz', 'When one of 500 charges fails', 'Promise.all and unhandled rejections behave differently from what most people expect. Answer before reading the section.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_114'), 'A refund job runs:

const receipts = await Promise.all(orders.map((o) => provider.refund(o)));

There are 500 orders. One refund rejects after 50 ms; the other 499 each take about 2 seconds. Which statements are true? Select all that apply.', 'multiple_choice'::question_type, 'Promise.all is fail-fast: it rejects with the first rejection, here after about 50 ms, and you lose the results of everything else. It cannot cancel anything - JavaScript promises have no cancellation, so the other 499 refunds keep running and many of them will succeed. After a failure the job must therefore reconcile what actually happened (or use Promise.allSettled to collect every outcome). Collecting all errors in an AggregateError is what Promise.any does when every promise rejects, not Promise.all.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_114') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('The await rejects after about 50 ms with that refund''s error.', true),
        ('The other 499 refunds are cancelled automatically when Promise.all rejects.', false),
        ('The other refunds keep running and may succeed, so the job must find out which ones went through.', true),
        ('Promise.all waits for all 500 and then rejects with an AggregateError listing every failure.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_114'), 'On Node.js 20, a background task does sendReceiptEmail(order) without await or .catch(), and the promise rejects. The process has no ''unhandledRejection'' listener. What happens?', 'single_choice'::question_type, 'Since Node.js 15 the default --unhandled-rejections mode is ''throw'': an unhandled rejection is raised as an uncaught exception and the process exits. Every request in flight on that instance fails with it. Always await or attach .catch() to background promises, and register process.on(''unhandledRejection'') only as a last-resort logger, not as a fix.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_114') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Nothing visible: the rejection is silently ignored.', false),
        ('A warning is printed and the process keeps running.', false),
        ('The rejection is raised as an uncaught exception and the process crashes, taking every in-flight request with it.', true),
        ('Node.js retries the rejected promise once before giving up.', false)
    ) AS o(option_text, is_correct);

