-- challenge chal_quiz_nhp_121 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_121', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-1-3' AND is_deleted = false LIMIT 1), 'version-conflict-quiz', 'UPDATE 0: what just happened?', 'A versioned update reports that it changed nothing. Decide what that means and what the code should do next.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_121'), 'The back-office loaded product 42 at version 7. On save, the API runs:

UPDATE products
SET price = 120, version = version + 1
WHERE id = 42 AND version = 7;

PostgreSQL answers UPDATE 0 (rowCount = 0). What does that mean, and what is the right reaction?', 'single_choice'::question_type, 'The WHERE clause matched no row: the product either no longer exists or its version is no longer 7, because someone else committed a change after you read it. Nothing was written, so no lost update happened - the conflict was detected. Re-running the same statement can never succeed, because the version will not go back to 7. The caller must re-read the row and either re-apply the change to the fresh data (for automatic, commutative changes) or hand the conflict to the user (for edits a person made on a stale screen). The application never sets the version to a guessed value; the database increments it.', 1, 10
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_121') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('The row was updated, but the driver did not report the affected row count; treat it as a success.', false),
        ('Another writer changed (or deleted) the row after version 7 was read. Nothing was written: re-read the row, then retry on fresh data or report a conflict.', true),
        ('PostgreSQL had the row locked; retry the same statement in a loop until it returns UPDATE 1.', false),
        ('The application should have incremented the version itself: send WHERE version = 8 instead.', false)
    ) AS o(option_text, is_correct);

