-- challenge chal_quiz_nhp_124 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_124', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-1-3' AND is_deleted = false LIMIT 1), 'optimistic-vs-pessimistic-quiz', 'Optimistic or pessimistic?', 'Optimistic concurrency is not free: it trades waiting for retrying. Pick the right tool for each workload.', 'open', 'hard'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_124'), 'Flash sale: 3,000 checkout requests per second all reserve stock on the same product row. Each request reads the row, checks stock, and writes with UPDATE ... WHERE id = $1 AND version = $2, retrying up to 3 times. What do you expect to see?', 'single_choice'::question_type, 'On a hot row almost every attempt conflicts: of all the requests that read the same version, only one can win, so the rest re-read and collide again. Most requests burn their 3 attempts - each one a full read plus a failed write - and fail with CONFLICT although stock is available, while database load multiplies. For a single hot counter, do the check inside one atomic statement (UPDATE products SET stock = stock - $1 WHERE id = $2 AND stock >= $1), or serialize with SELECT ... FOR UPDATE, or a queue. Optimistic control shines when conflicts are rare.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_124') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Throughput is excellent, because optimistic concurrency never waits for locks.', false),
        ('Most requests exhaust their retries and fail with CONFLICT while stock is still available, and the database does several times the work per sale.', true),
        ('PostgreSQL detects the contention and automatically switches the statement to row locking.', false),
        ('Requests are queued fairly by the version column, so each one succeeds on its second attempt.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_124'), 'Which of these are good fits for optimistic concurrency control (a version column checked on write)? Select all that apply.', 'multiple_choice'::question_type, 'Optimistic control fits when conflicts are rare and the time between read and write is long or spans requests: you cannot hold a database lock while a merchant keeps an edit form open for ten minutes, or while a mobile client is offline, but you can send the version along and check it on save. It is a poor fit for a hot row where conflicts are the normal case, and for a critical step that must not fail under contention - there, a single atomic statement or a pessimistic lock (SELECT ... FOR UPDATE inside a short transaction) is the better tool.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_124') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('A merchant edits a product description in the back-office and may keep the form open for ten minutes before saving.', true),
        ('A shared wallet balance updated by thousands of micro-payments per second.', false),
        ('A mobile app that edits a customer''s saved addresses offline and syncs them later.', true),
        ('A short transaction that must debit a hot settlement account and is not allowed to fail because of contention.', false)
    ) AS o(option_text, is_correct);

