-- challenge chal_quiz_nhp_201 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_201', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-2-1' AND is_deleted = false LIMIT 1), 'idempotency-key-scope-quiz', 'Where does the Idempotency-Key come from?', 'The mobile app retries POST /payments when the network drops. Decide how the client should generate the key so a retry is recognised as the same payment.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_201'), 'A customer taps "Pay 80,000" once. The app sends POST /payments, the response is lost on a flaky 4G connection, and the HTTP client retries twice. Later the same customer intentionally buys a second, identical 80,000 item. Which way of choosing the Idempotency-Key charges exactly once per purchase?', 'single_choice'::question_type, 'The key identifies one payment intent, not one HTTP attempt. Generating a UUID when the user confirms the checkout and reusing it for every retry of that request lets the server recognise retries and replay the first response. A new key per attempt makes every retry look like a new payment. A key derived from wallet + amount collapses two genuine purchases of the same amount into one. A server-generated key cannot help, because the client never received the response that carried it.', 1, 10
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_201') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Generate a new UUID for every HTTP attempt, so each request is unique and easy to trace.', false),
        ('Generate a UUID once when the user confirms the checkout, store it with the pending payment and send the same value on every retry of that request.', true),
        ('Use a hash of walletId + amount + currency, so identical requests always get the same key.', false),
        ('Let the server generate the key and return it in the response; the client sends it back on retries.', false)
    ) AS o(option_text, is_correct);

