-- challenge chal_quiz_nhp_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_211', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-2-2' AND is_deleted = false LIMIT 1), 'what-to-retry-quiz', 'What is worth retrying - and how often?', 'Not every failure gets better with another attempt, and every retry is extra load on a service that may already be struggling.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_211'), 'The checkout service calls a fraud-scoring API with POST /score. The call is read-only and safe to repeat. Which failures should the client retry automatically (with backoff)? Select all that apply.', 'multiple_choice'::question_type, '503 and a timeout are transient: the server was overloaded or the response never arrived, and a later attempt may succeed. 429 means ''slow down'' - retry, but no sooner than the Retry-After header says. 400 means the request itself is invalid; sending the same bytes again will fail again and only adds load. Note that all of this is only safe because /score has no side effects - a timed-out POST /payments must not be blindly retried without an idempotency key.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('503 Service Unavailable', true),
        ('The request timed out after 800 ms (ETIMEDOUT)', true),
        ('400 Bad Request: "currency must be a 3-letter ISO code"', false),
        ('429 Too Many Requests with Retry-After: 2', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_211'), 'A request goes mobile app -> API gateway -> checkout service -> fraud API. The gateway, the checkout service and the fraud client each retry up to 3 times (4 attempts each) on timeouts. The fraud API slows down so every call to it times out. In the worst case, how many requests reach the fraud API for one tap of the user?', 'single_choice'::question_type, 'Retries multiply across layers: each of the 4 gateway attempts makes the checkout service try 4 times, and each of those makes the fraud client try 4 times: 4 x 4 x 4 = 64 calls to a service that is already failing. This is how a slowdown becomes a retry storm. Retry at one layer only (usually the one closest to the failing dependency), cap retries with a retry budget, and let the outer layers fail fast.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('4 - each layer''s retries replace each other.', false),
        ('12 - three layers with 4 attempts each.', false),
        ('64 - the attempts multiply: 4 x 4 x 4.', true),
        ('Unlimited - retries never stop while the API is slow.', false)
    ) AS o(option_text, is_correct);

