-- challenge chal_quiz_nhp_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_221', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-2-3' AND is_deleted = false LIMIT 1), 'dual-write-quiz', 'Commit, then publish: what can go wrong?', 'The top-up handler writes to PostgreSQL and then publishes an event for the wallet service. Find the gap between the two writes.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_221'), 'A top-up handler runs:

await db.query("BEGIN");
await db.query("INSERT INTO topups ...");
await db.query("COMMIT");
await kafka.send({ topic: "wallet-events", messages: [walletCredited] });

The pod is OOM-killed right after COMMIT returns, before kafka.send() runs. What is the result?', 'single_choice'::question_type, 'The top-up row is committed but the event is never published, and nothing will ever publish it: the only record of "I still have to publish" lived in the memory of the killed process. The customer paid, but the wallet is never credited. Swapping the order (publish first, then commit) just flips the failure: an event for a top-up that was rolled back. A database and a broker cannot share one transaction, so the fix is to make the event part of the database transaction (an outbox row) and publish it afterwards from there.', 1, 10
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Nothing is lost: Node.js flushes pending Kafka sends when the process exits.', false),
        ('The top-up is committed but the WalletCredited event is never published, so the wallet is never credited - and no retry will ever notice.', true),
        ('PostgreSQL rolls the top-up back because the request did not finish.', false),
        ('Kafka detects the missing message and asks the producer to resend it after restart.', false)
    ) AS o(option_text, is_correct);

