-- challenge chal_quiz_nhp_301 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_301', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-3-1' AND is_deleted = false LIMIT 1), 'fixed-window-boundary-burst-quiz', 'How many requests fit through a fixed window?', 'A fixed-window counter looks like it enforces "100 per minute". Check what it really allows before you rely on it.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_301'), 'The payment API limits each API key to 100 requests per minute with a fixed-window counter: the Redis key is ratelimit:<apiKey>:<current minute>, incremented on every request and rejected above 100. A misbehaving client sends 100 POST /payments at 12:00:59.900 and another 100 at 12:01:00.100. What happens?', 'single_choice'::question_type, 'The two bursts land in different windows (minute 12:00 and minute 12:01), and each window''s counter only reaches 100, so all 200 requests are accepted within about 200 ms - twice the intended rate. Fixed windows forget everything at the boundary. A sliding window (or a sliding-window counter that weights the previous window) or a token bucket bounds the burst no matter where the boundary falls.', 1, 10
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_301') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Only the first 100 are accepted: the limiter sees 200 requests in less than a minute and rejects the second burst.', false),
        ('All 200 are accepted within about 200 ms, because each burst falls into a different window whose counter only reaches 100.', true),
        ('The second burst is accepted only after the client waits until 12:01:59, when the first burst is a full minute old.', false),
        ('Half of each burst is rejected, because a fixed window spreads the 100-request budget evenly over the minute.', false)
    ) AS o(option_text, is_correct);

