-- challenge chal_quiz_nhp_303 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_303', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-3-1' AND is_deleted = false LIMIT 1), 'redis-incr-expire-quiz', 'Sharing one limit across API instances', 'Six API instances must enforce the same per-key limit. Review the Redis code before it ships.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_303'), 'Six instances of the payment API share this limiter:

const count = await redis.incr(key);
if (count === 1) await redis.expire(key, 60);
if (count > 100) return reply429();

Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'INCR is atomic, so two instances can never both see count === 1 and no increment is lost. The weak spot is the gap between the two commands: if the process crashes or the connection drops after INCR and before EXPIRE, the key has no TTL, keeps counting forever and that API key is rate limited permanently. Sending INCR and EXPIRE together in one Lua script (or a MULTI block) closes the gap. Per-instance in-memory counters are not equivalent: behind a load balancer each instance allows its own 100, so the client gets up to 600 per minute.', 1, 10
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_303') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Two instances can both read count === 1 for the same key and each believe they started the window.', false),
        ('If the process dies between INCR and EXPIRE, the key never expires and that client stays rate limited forever.', true),
        ('Running INCR and EXPIRE in a single Lua script (or MULTI/EXEC) makes the pair atomic and removes that failure mode.', true),
        ('Keeping the counter in each instance''s memory instead of Redis gives the same overall limit with less latency.', false)
    ) AS o(option_text, is_correct);

