-- challenge chal_quiz_nhp_311 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_311', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-3-2' AND is_deleted = false LIMIT 1), 'hot-key-expiry-stampede-quiz', 'What happens when the hot key expires?', 'The flash-sale product page is served from Redis with plain cache-aside. Predict the moment its key expires.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_311'), 'During a flash sale, GET /products/sku-123 receives 3,000 requests per second, spread over 8 API instances. Each instance does:

let product = await redis.get(key);
if (!product) {
  product = await db.loadProduct(id);   // ~400 ms under load
  await redis.set(key, product, { EX: 60 });
}

The key expires at 20:00:00. What happens in the next half second?', 'single_choice'::question_type, 'Every request that arrives before the first loader finishes also sees a miss. At 3,000 rps with a 400 ms query, that is roughly 1,200 requests, all running the same expensive query at once. The extra load makes the query slower, which widens the window and lets even more requests miss - the classic cache stampede (thundering herd). Redis does not coalesce misses for you; you need single-flight per key (per process, or a short Redis lock across processes), stale-while-revalidate, or early refresh.', 1, 10
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_311') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('One request reloads the product; the others wait automatically because Redis serializes reads of the same key.', false),
        ('Each of the 8 instances sends exactly one query, because Node.js handles one request at a time per instance.', false),
        ('Every request that misses before the first reload finishes runs the query - on the order of a thousand concurrent queries, which slows the database and widens the window further.', true),
        ('Requests receive an error until the key is re-created, because cache-aside never reads the database on the hot path.', false)
    ) AS o(option_text, is_correct);

