-- challenge chal_quiz_nhp_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_321', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-3-3' AND is_deleted = false LIMIT 1), 'write-returns-false-quiz', 'What does write() returning false mean?', 'The export loop calls res.write() for every ledger row. Read what the return value is telling you.', 'open', 'easy'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_321'), 'An export handler writes CSV lines to the HTTP response with res.write(line) in a loop. After a few hundred lines, res.write() starts returning false. What does that mean, and what should the loop do?', 'single_choice'::question_type, 'write() returning false is backpressure, not an error: the chunk WAS accepted and queued, but the stream''s internal buffer has reached its highWaterMark because the destination (here, a slow client connection) is consuming more slowly than you produce. Writing more only grows the buffer in memory. The producer should pause and resume when the stream emits ''drain''. Retrying the same chunk would duplicate it, and nothing is dropped automatically.', 1, 10
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('The line was rejected and lost; the loop must write the same line again until write() returns true.', false),
        ('The line was queued, but the buffer is at its highWaterMark; stop writing and continue after the ''drain'' event.', true),
        ('The client disconnected; the loop should stop and call res.end().', false),
        ('Nothing important: Node.js grows the buffer automatically, so the loop can keep writing at full speed.', false)
    ) AS o(option_text, is_correct);

