-- challenge chal_quiz_nhp_401 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_401', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-4-1' AND is_deleted = false LIMIT 1), 'cpu-bound-strategy-quiz', 'Chunking, worker threads or cluster?', 'Three tools, three different problems. Pick the one that actually removes the blocking - and spot the claims that sound right but are not.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_401'), 'POST /fraud/score-batch spends about 400 ms of pure JavaScript CPU per call (an in-memory scoring model). While it runs, the p99 of POST /payments on the same instance jumps from 40 ms to 450 ms. The service is a single Node.js process on a 4 vCPU VM. Which change best fixes /payments latency while keeping scoring throughput?', 'single_choice'::question_type, 'The scoring is CPU work on the main thread, so every other request waits until it finishes. A worker_threads pool moves it off the event loop and uses the idle cores, and a bounded queue stops a burst of batches from piling up unbounded. Marking the function async changes nothing - the CPU work still runs synchronously on the same thread. process.nextTick callbacks run before the event loop gets back to I/O, so they do not let /payments in. Cluster spreads requests across processes, but any /payments request that lands on the process currently scoring still waits the full 400 ms.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_401') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Declare the scoring function async and await it in the handler, so it no longer blocks.', false),
        ('Run the scoring in a worker_threads pool (for example piscina) sized to the spare cores, with a bounded queue.', true),
        ('Start 4 processes with cluster: the load is spread, so scoring can no longer delay a payment.', false),
        ('Call process.nextTick() every 100 transactions inside the scoring loop to let other requests run.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_401'), 'Which statements are true? (Select all that apply.)', 'multiple_choice'::question_type, 'cluster forks full processes: each has its own heap and event loop and the primary hands out connections on the shared port. Worker threads are separate V8 isolates - they do not see each other''s variables and communicate through postMessage (structured clone), transferred ArrayBuffers or a SharedArrayBuffer. Chunking does not reduce the total CPU time - it only interleaves other callbacks between chunks, which is enough when the work is moderate. Creating a Worker costs milliseconds and several MB of memory, so a reusable pool beats one Worker per request.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_401') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('cluster forks separate processes that share the listening port; each has its own memory and its own event loop.', true),
        ('Worker threads share one JavaScript heap, so a worker can read the main thread''s variables directly.', false),
        ('Chunking with setImmediate keeps all work on the main thread: total CPU time stays the same, but other requests are served between chunks.', true),
        ('Spawning a new Worker for every request is cheaper than keeping a pool, because threads are lightweight.', false)
    ) AS o(option_text, is_correct);

