INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_411', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-4-2' AND is_deleted = false LIMIT 1), 'probes-and-shutdown-order-quiz', 'Readiness, liveness and the shutdown order', 'Probes decide when Kubernetes sends traffic and when it restarts your pod. The shutdown order decides whether in-flight payments survive a deploy.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_411'), 'The payments API exposes two probe endpoints to Kubernetes. During a planned 40-second Postgres failover, what should the probes do?', 'single_choice'::question_type, 'Readiness answers ''should this pod receive traffic right now?'' - returning 503 while a hard dependency is down (or while shutting down) takes the pod out of the Service without killing it. Liveness answers ''is this process stuck and in need of a restart?'' and should only test the process itself. If liveness checks the database, every pod fails it at the same time and Kubernetes restarts the whole fleet in a loop during the failover, turning a 40-second blip into an outage. Without probes, a hung process keeps receiving traffic forever.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_411') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Liveness checks the database, so Kubernetes restarts the pods until the database is back.', false),
        ('Readiness returns 503 while the database is unreachable; liveness only checks that the process itself still responds.', true),
        ('Both probes call the same endpoint that runs SELECT 1, so they always agree.', false),
        ('Disable both probes: Kubernetes already notices crashed processes, and probes only add load.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_411'), 'A rolling update sends SIGTERM to a payments pod (terminationGracePeriodSeconds: 30). Which sequence keeps in-flight payments safe?', 'single_choice'::question_type, 'First make the pod unready and give the endpoints a few seconds to stop routing to it, then stop accepting new connections with server.close(). In-flight requests are allowed to finish, but under a deadline shorter than the grace period - otherwise SIGKILL arrives first and nothing is cleaned up. Only when no request can still need them are the database and Redis pools closed. Closing the pool first fails the very requests you are waiting for; exiting immediately drops them; waiting forever on keep-alive connections ends in SIGKILL.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_411') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Close the database pool, then call server.close(), then exit.', false),
        ('Fail readiness and wait briefly, call server.close(), wait for in-flight requests up to a deadline below 30 s, close DB/Redis pools, exit 0.', true),
        ('Call process.exit(0) right away: the load balancer will retry the requests that were cut off.', false),
        ('Call server.close() and wait for every keep-alive connection to close by itself, however long it takes, then close the database.', false)
    ) AS o(option_text, is_correct);

