-- challenge chal_quiz_nhp_421 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nhp_421', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-high-performance') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nodejs-hp-4-3' AND is_deleted = false LIMIT 1), 'average-vs-p99-quiz', 'What the average hides', 'Read a latency distribution the way an on-call engineer must: who is having a bad time, and which number shows it?', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_421'), 'In 5 minutes the checkout endpoint served 10,000 requests: 9,850 took about 50 ms, and 150 took about 3,000 ms (waiting on a hot database row). The mobile app gives up after 2.5 s. The dashboard shows the average. Which statement is correct?', 'single_choice'::question_type, 'The average is (9,850 x 50 + 150 x 3,000) / 10,000 = about 94 ms, which looks healthy and is far below the timeout. But the slowest 1.5% of requests - 150 real customers - took 3 s and saw an error. With the nearest-rank definition, p99 is the value at rank 9,900, which falls inside the slow group, so p99 = 3,000 ms while p50 = 50 ms. Averages blend two very different populations into a number that describes neither; percentiles describe how many users experienced at least that latency.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_421') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('The average is about 94 ms, far below 2.5 s, so no customer is affected.', false),
        ('The average is about 94 ms, but p99 is 3,000 ms: 1.5% of checkouts exceed the client timeout, and only the tail percentiles show it.', true),
        ('The average is about 1,525 ms, halfway between the fast and the slow requests.', false),
        ('p50 is 3,000 ms, because the slow requests dominate the total time.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_421'), 'Which statements about latency metrics and event loop delay are true? (Select all that apply.)', 'multiple_choice'::question_type, 'Percentiles cannot be averaged: the mean of ten per-instance p99s is not the p99 of the combined traffic (one hot instance gets diluted). Export histograms - bucket counts add up across instances - and compute the quantile on the summed buckets, for example histogram_quantile(0.99, sum by (le) (rate(http_request_duration_seconds_bucket[5m]))). Event loop delay measures how late callbacks run: when it rises while traffic is flat, requests are queueing inside the process before any handler code starts. It is not only a CPU-heavy-service problem - GC pauses, large JSON.parse/stringify, synchronous logging or crypto on the main thread all show up there.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nhp_421') AND order_index = 2)
    RETURNING id
)
